def audited(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        sink.record(current_subject(), fn.__name__, "attempt")
        try:
            result = fn(*args, **kwargs)
        except Exception:
            sink.record(current_subject(), fn.__name__, "failed"); raise
        sink.record(current_subject(), fn.__name__, "ok")
        return result
    return wrapper
# usage: @audited on the audited operation

