import sys

AUDITED = {"open", "os.system", "socket.connect", "subprocess.Popen"}


def hook(event, args):
    if event in AUDITED:
        sink.record(actor=current_subject(), action=event,
                    target=repr(args[0]), outcome="observed")


sys.addaudithook(hook)          # installed for the process lifetime
